<?php
namespace App\Models;
use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;use Laravel\Sanctum\HasApiTokens;use Illuminate\Database\Eloquent\Factories\HasFactory;
class User extends Authenticatable{use HasApiTokens,HasFactory,Notifiable;protected $fillable=['name','email','phone','role','password','address','city','avatar','is_active'];protected $hidden=['password','remember_token'];protected function casts():array{return ['password'=>'hashed','is_active'=>'boolean'];}public function services(){return $this->hasMany(Service::class,'provider_id');}public function customerBookings(){return $this->hasMany(Booking::class,'customer_id');}public function providerBookings(){return $this->hasMany(Booking::class,'provider_id');}public function isAdmin():bool{return $this->role==='admin';}public function isProvider():bool{return $this->role==='provider';}}
